// A reusable polygon graph component
Vue.component('polygraph', {
    props: ['stats'],
    template: '#polygraph-template',
    computed: {
        // a computed property for the polygon's points
        points: function () {
            var total = this.stats.length
            return this.stats.map(function (stat, i) {
                var point = valueToPoint(stat.value, i, total)
                return point.x + ',' + point.y
            }).join(' ')
        }
    },
    components: {
        // a sub component for the labels
        'axis-label': {
            props: {
                stat: Object,
                index: Number,
                total: Number
            },
            template: '#axis-label-template',
            computed: {
                point: function () {
                    return valueToPoint(
                        +this.stat.value + 10,
                        this.index,
                        this.total
                    )
                }
            }
        }
    }
})

function dijkstra(graph, s) {
    const distance = {};
    const previous = {};
    const q = new PriorityQueue();
    // Initialize
    distance[s] = 0;
    graph.vertices.forEach(v => {
        if (v !== s) {
            distance[v] = Infinity;
        }
        q.insert(v, distance[v]);
    });

    let currNode;
    const relax = v => {
        const newDistance = distance[currNode] + graph.edge(currNode, v);
        if (newDistance < distance[v]) {
            distance[v] = newDistance;
            previous[v] = currNode;
            q.changePriority(v, distance[v]);
        }
    };
    while (!q.isEmpty()) {
        currNode = q.extract();
        graph.neighbors(currNode).forEach(relax);
    }
    return {
        distance,
        previous
    };
}

class BezierCurve {
	constructor(points) {
		this.n = points.length;
		this.p = [];

		// The binomial coefficient
		const c = [1];
		let i;
		let j;
		for (i = 1; i < this.n; ++i) {
			c.push(0);
			for (j = i; j >= 1; --j) {
				c[j] += c[j - 1];
			}
		}

		// the i-th control point times the coefficient
		for (i = 0; i < this.n; ++i) {
			this.p.push({x: c[i] * points[i].x, y: c[i] * points[i].y});
		}
	}

	/**
	 * @param Number float variable from 0 to 1
	 */
	get(t) {
		const res = {x: 0, y: 0};
		let i;
		let a = 1;
		let b = 1;

		// The coefficient
		const c = [];
		for (i = 0; i < this.n; ++i) {
			c.push(a);
			a *= t;
		}

		for (i = this.n - 1; i >= 0; --i) {
			res.x += this.p[i].x * c[i] * b;
			res.y += this.p[i].y * c[i] * b;
			b *= 1 - t;
		}
		return res;
	}
}

